// Query represents parsed filter/query
type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	HasDue        bool
	DateFilter    string
	Priority      string
	Template      int
	HasTemplate   bool
	Text          string
	IgnoreContext bool
	Note          string
}

func isNumeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func parseDueValue(v string) (time.Time, bool) {
	orig := v
	v = strings.ToLower(strings.TrimSpace(v))
	if v == "" {
		return time.Time{}, false
	}
	_ = orig
	now := time.Now()
	// Use UTC? Original uses UTC midnight. Today based on local or UTC? Use local date but UTC midnight?
	// Let's use current time in local, then construct UTC midnight for due.
	// Actually original due is UTC midnight. Today is based on system date (which is UTC in container).
	// We'll use time.Now().UTC() for date components.
	utcNow := now.UTC()
	today := time.Date(utcNow.Year(), utcNow.Month(), utcNow.Day(), 0, 0, 0, 0, time.UTC)

	if v == "today" {
		return today, true
	}
	if v == "tomorrow" {
		return today.AddDate(0, 0, 1), true
	}
	if v == "yesterday" {
		return today.AddDate(0, 0, -1), true
	}

	// next-<weekday>
	if strings.HasPrefix(v, "next-") {
		wdStr := strings.TrimPrefix(v, "next-")
		wd, ok := parseWeekday(wdStr)
		if !ok {
			return time.Time{}, false
		}
		// upcoming including today, then +7
		upcoming := upcomingWeekday(today, wd)
		return upcoming.AddDate(0, 0, 7), true
	}
	// weekday
	if wd, ok := parseWeekday(v); ok {
		return upcomingWeekday(today, wd), true
	}

	// YYYY-MM-DD
	if len(v) == 10 && v[4] == '-' && v[7] == '-' {
		yStr, mStr, dStr := v[0:4], v[5:7], v[8:10]
		y, err1 := strconv.Atoi(yStr)
		m, err2 := strconv.Atoi(mStr)
		d, err3 := strconv.Atoi(dStr)
		if err1 != nil || err2 != nil || err3 != nil {
			return time.Time{}, false
		}
		// strict: must be exactly digits, 4-2-2
		if len(yStr) != 4 || len(mStr) != 2 || len(dStr) != 2 {
			return time.Time{}, false
		}
		if !validDate(y, m, d) {
			return time.Time{}, false
		}
		return time.Date(y, time.Month(m), d, 0, 0, 0, 0, time.UTC), true
	}
	// MM-DD
	if len(v) == 5 && v[2] == '-' {
		mStr, dStr := v[0:2], v[3:5]
		m, err1 := strconv.Atoi(mStr)
		d, err2 := strconv.Atoi(dStr)
		if err1 != nil || err2 != nil {
			return time.Time{}, false
		}
		if len(mStr) != 2 || len(dStr) != 2 {
			return time.Time{}, false
		}
		y := utcNow.Year()
		if !validDate(y, m, d) {
			return time.Time{}, false
		}
		return time.Date(y, time.Month(m), d, 0, 0, 0, 0, time.UTC), true
	}
	// DD (1-2 digits)
	if len(v) >= 1 && len(v) <= 2 && isNumeric(v) {
		d, _ := strconv.Atoi(v)
		if d < 1 || d > 31 {
			return time.Time{}, false
		}
		// Use Date normalization (e.g., Sep 31 -> Oct 1)
		return time.Date(utcNow.Year(), utcNow.Month(), d, 0, 0, 0, 0, time.UTC), true
	}

	return time.Time{}, false
}

func validDate(y, m, d int) bool {
	if m < 1 || m > 12 || d < 1 {
		return false
	}
	days := daysInMonth(y, m)
	return d <= days
}

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeap(y) {
			return 29
		}
		return 28
	}
	return 0
}

func isLeap(y int) bool {
	return y%4 == 0 && (y%100 != 0 || y%400 == 0)
}

func parseWeekday(s string) (time.Weekday, bool) {
	switch s {
	case "mon", "monday":
		return time.Monday, true
	case "tue", "tues", "tuesday":
		return time.Tuesday, true
	case "wed", "wednesday":
		return time.Wednesday, true
	case "thu", "thur", "thurs", "thursday":
		return time.Thursday, true
	case "fri", "friday":
		return time.Friday, true
	case "sat", "saturday":
		return time.Saturday, true
	case "sun", "sunday":
		return time.Sunday, true
	}
	return time.Sunday, false
}

