func isNumeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func parseDueValue(v string) (time.Time, bool) {
	orig := v
	v = strings.ToLower(strings.TrimSpace(v))
	if v == "" {
