		return upcoming.AddDate(0, 0, 7), true
	}
	// weekday
	if wd, ok := parseWeekday(v); ok {
		return upcomingWeekday(today, wd), true
	}

	// YYYY-MM-DD
	if len(v) == 10 && v[4] == '-' && v[7] == '-' {
		yStr, mStr, dStr := v[0:4], v[5:7], v[8:10]
		y, err1 := strconv.Atoi(yStr)
		m, err2 := strconv.Atoi(mStr)
		d, err3 := strconv.Atoi(dStr)
		if err1 != nil || err2 != nil || err3 != nil {
			return time.Time{}, false
		}
		// strict: must be exactly digits, 4-2-2
		if len(yStr) != 4 || len(mStr) != 2 || len(dStr) != 2 {
			return time.Time{}, false
		}
		if !validDate(y, m, d) {
			return time.Time{}, false
		}
		return time.Date(y, time.Month(m), d, 0, 0, 0, 0, time.UTC), true
	}
	// MM-DD
	if len(v) == 5 && v[2] == '-' {
		mStr, dStr := v[0:2], v[3:5]
		m, err1 := strconv.Atoi(mStr)
		d, err2 := strconv.Atoi(dStr)
		if err1 != nil || err2 != nil {
			return time.Time{}, false
		}
		if len(mStr) != 2 || len(dStr) != 2 {
			return time.Time{}, false
		}
