}

func saveTask(repo string, t Task) error {
	ft := fileTask{
		Summary:      t.Summary,
		Notes:        t.Notes,
		Tags:         t.Tags,
		Project:      t.Project,
		Priority:     t.Priority,
		DelegatedTo:  t.DelegatedTo,
		Subtasks:     t.Subtasks,
		Dependencies: t.Dependencies,
		Created:      t.Created,
		Resolved:     t.Resolved,
		Due:          t.Due,
	}
	if ft.Tags == nil {
		ft.Tags = []string{}
	}
	if ft.Subtasks == nil {
		ft.Subtasks = []string{}
	}
	if ft.Dependencies == nil {
		ft.Dependencies = []string{}
	}
	data, err := yaml.Marshal(&ft)
	if err != nil {
		return err
	}
	dir := filepath.Join(repo, t.Status)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return err
	}
	path := filepath.Join(dir, t.UUID+".yml")
	// Write with 0600
	return os.WriteFile(path, data, 0600)
}

func priorityValue(p string) int {
	switch p {
	case "P0":
		return 0
	case "P1":
		return 1
	case "P2":
		return 2
	case "P3":
		return 3
	default:
		return 2
	}
}

func sortTasks(tasks []Task) {
	sort.Slice(tasks, func(i, j int) bool {
		pi, pj := priorityValue(tasks[i].Priority), priorityValue(tasks[j].Priority)
		if pi != pj {
			return pi < pj
		}
		if !tasks[i].Created.Equal(tasks[j].Created) {
