func getRepoPath() string {
	if v := os.Getenv("DSTASK_GIT_REPO"); v != "" {
		return v
	}
	home, _ := os.UserHomeDir()
	if home == "" {
		home = os.Getenv("HOME")
	}
	return filepath.Join(home, ".dstask")
}

func ensureRepo(repo string) (bool, string, string) {
