func loadState(repo string) (State, error) {
	var s State
	path := filepath.Join(repo, ".git", "dstask", "state.bin")
	data, err := os.ReadFile(path)
	if err != nil {
		return s, err // no state yet, return empty (caller will handle)
	}
	dec := gob.NewDecoder(bytes.NewReader(data))
	// Need to register types? Query contains time.Time, slices, etc. Gob should handle.
	if err := dec.Decode(&s); err != nil {
		return State{}, err
	}
	return s, nil
}

func saveState(repo string, s State) error {
	var buf bytes.Buffer
	enc := gob.NewEncoder(&buf)
	if err := enc.Encode(&s); err != nil {
		return err
	}
	dir := filepath.Join(repo, ".git", "dstask")
	if err := os.MkdirAll(dir, 0700); err != nil {
