func getTermWidth() int {
	// Try ioctl on stdout, fallback to 80
	fd := int(os.Stdout.Fd())
	var ws struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno == 0 && ws.Col != 0 {
		return int(ws.Col)
	}
	// Try stderr? Or stdin? For FAKE_PTY with piped stdout, ioctl will fail, fallback to 80.
	return 80
}

func isOverdueOrToday(due time.Time) bool {
	if due.IsZero() {
		return false
	}
	// Compare date (UTC) <= today (UTC)
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	d := time.Date(due.UTC().Year(), due.UTC().Month(), due.UTC().Day(), 0, 0, 0, 0, time.UTC)
	return !d.After(today) // d <= today
}

func dueDisplay(due time.Time) string {
	if due.IsZero() || due.Year() == 1 {
		return ""
	}
	now := time.Now().UTC()
	today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)
	d := time.Date(due.UTC().Year(), due.UTC().Month(), due.UTC().Day(), 0, 0, 0, 0, time.UTC)
	diff := int(d.Sub(today).Hours() / 24)
	if diff == 0 {
		return "today"
	}
	if diff == 1 {
		return "tomorrow"
	}
	if diff == -1 {
		return "yesterday"
	}
	// Same year? Format "2 Jan" vs "2 Jan 2006"
	if d.Year() == today.Year() {
		return d.Format("2 Jan")
	}
	return d.Format("2 Jan 2006")
}

