	// Determine foreground based on priority and due
	overdue := isOverdueOrToday(t.Due)
	var pendingFg string
	switch t.Priority {
	case "P0":
		pendingFg = "160"
	case "P1":
		pendingFg = "166"
	case "P2":
		if overdue {
