func padTruncate(s string, w int) string {
	// Truncate to w runes? Original truncates by bytes? For ASCII, same. For unicode? Assume bytes/runes same for ASCII. Use runes for safety.
	runes := []rune(s)
	if len(runes) > w {
		runes = runes[:w]
		s = string(runes)
	}
	if len(s) < w {
		// Pad with spaces (need to handle rune vs byte? For ASCII, len==runes. For simplicity, pad based on rune len)
		pad := w - len([]rune(s))
		s += strings.Repeat(" ", pad)
	}
	return s
}

