	// Format: "\x1b[38;5;160m<N> critical task(s) outside this context! Use `dstask -- P0` to see them.\x1b[0m\n" to stdout.
	// When to print? Only in TTY mode? For non-TTY JSON, no warning. Good. This function only called in TTY.
	// Need to determine "outside": all open P0 tasks minus filtered P0 tasks? Or all open P0 minus filtered (any)? Example: filtered is [P2 tasks], outside P0 count 2. Good.
	// What about filtered includes some P0 but not all? Example: filtered is [P0 task 1] (detail for 1, with P0 task 2 outside), warning says 1 outside. Good. So count = total P0 open - P0 in filtered.
	// What about when filtered is all open (no filter)? Then outside 0, no warning. Good.
	// What about when filtered is show-active (only active)? Outside includes P0 pending/paused (not active). That's why show-active with P2 active and P0 paused outside gave warning. Good.
	// So count all open P0 not in filtered (by UUID).
	// Need all open tasks (pending/active/paused) from a.Tasks.
	filteredUUIDs := make(map[string]bool)
	for _, t := range filtered {
		filteredUUIDs[t.UUID] = true
	}
	count := 0
	for _, t := range a.Tasks {
		if t.Status != "pending" && t.Status != "active" && t.Status != "paused" {
			continue
		}
		if t.Priority != "P0" {
			continue
		}
		if !filteredUUIDs[t.UUID] {
			count++
		}
	}
	if count > 0 {
		msg := fmt.Sprintf("%d critical task(s) outside this context! Use `dstask -- P0` to see them.", count)
		// Note: original message uses "1 critical task(s)" even for singular (with "(s)" always). Good, always "(s)".
		fmt.Printf("\x1b[38;5;160m%s\x1b[0m\n", msg)
	}
}
